// Flux Studio screen texts. Keys are the English source strings of Flux Studio (the same ones the plugin's
// language packs translate), so PHP and the screen share one wording. Placeholders: {name}.
// The dictionaries are generated by plugins/flx-studio/tools/i18n-react.py.
import { normalizeLocale } from '@fluxwp/core';
import tr from './i18n/tr.json';
import de from './i18n/de.json';
import es from './i18n/es.json';
import fr from './i18n/fr.json';
import ptBr from './i18n/pt-br.json';
import ja from './i18n/ja.json';
import zh from './i18n/zh.json';
import ar from './i18n/ar.json';
import ru from './i18n/ru.json';

const dicts: Record<string, Record<string, string>> = { tr, de, es, fr, 'pt-br': ptBr, ja, zh, ar, ru };

export type Vars = Record<string, string | number>;
export type Translate = (source: string, vars?: Vars) => string;

export function translator(locale: string): Translate {
  const d = dicts[normalizeLocale(locale)] ?? {};
  return (source, vars) => (d[source] ?? source).replace(/\{(\w+)\}/g, (m, k: string) => (vars && k in vars ? String(vars[k]) : m));
}

/** Locale tag for number and date formatting. */
export function numberLocale(locale: string): string {
  return locale.replace('_', '-') || 'en';
}
